        environment: [String: String] = ProcessInfo.processInfo.environment
    ) -> any SecretStore {
        let folderKey = AssemblyAIConfiguration.secretFolderArgument
        if let folder = AssemblyAIConfiguration.argument(folderKey, defaults: defaults) {
            return FileStore(
