static func firstExtraTrackID(_ plan: CompositionPlan) -> Int {
    let planIDs = plan.videoTracks.map(\.id) + plan.audioTracks.map(\.id)
    return max(placeholderTrackID(plan), planIDs.max() ?? 0) + 1
